class Configuration(CommonPage):
    """
    The class corresponding to Configuration page on selenium_coam web, all operations under Configuration
    page will be implemented or added in its corresponding classes.
    """
    _instance_dict = {}

    def __init__(self, driver, version):
        if not self._instance_dict:
            self._instance_dict = {
                "Parameter Editor": ParameterEditorPage(driver, version),
                "Compare Objects": CompareObjectsPage(driver, version)
            }
        super(Configuration, self).__init__(driver, version, self._instance_dict)


class ConfigurationCommonAction(NavigationPanel, ViewPanel, DetailPanel):

    def __init__(self, driver, version):
        self.driver = driver
        self.version = version
        super(ConfigurationCommonAction, self).__init__(driver, version)

    def _get_valid_object_xpath(self, object_name, last_level_object_name, timeout=60):
        """
        get the valid object out of all the matching object via filter and select the proper one

        :param object_name: str , name of the model object
        :param last_level_object_name: str, level of the object
        :param timeout: int, timeout for the element be available to click
        """
        object_xpath_list = self._get_object_xpath_list(last_level_object_name, timeout)
        for element in object_xpath_list:
            element.click()
            if self.element_exists(self.locator.CHECK_OBJECT_NAME_XPATH.format(object_name), timeout=10):
                return

    def _get_object_xpath_list(self, object_name, timeout):
        """
        This Keyword to get all the matching xpaths to the given object

        :param object_name: str , name of the model object
        :param timeout: int, timeout for the element be available to click

        :return: All the matching web elements
        """
        self.wait_for_visibility(self.locator.OBJECT_NAME_XPATH.format(object_name), timeout)
        return self.get_all_matching_elements(self.locator.OBJECT_NAME_XPATH.format(object_name))

    def filter_and_select_the_object(self, object_name, timeout=60):
        """
        filter the Model object for the selected plan and select it

        :param object_name: str, where object will be added in
        :param timeout: int, timeout for the element be available to click
        """
        last_level_object_name = object_name.split('/')[-1]
        self._load_the_filter()
        self._clear_mo_filter()
        self.insert_text_to_enable_element_and_enter(self.locator.OBJECT_NAME_FILTER_XPATH,
                                                     last_level_object_name, timeout)
        self._get_valid_object_xpath(object_name, last_level_object_name, timeout)

    def _clear_mo_filter(self):
        """
        This keyword will clear content present in the object filter box
        :return:
        """
        if self.element_exists(self.locator.CLEAR_FILTER_XPATH, timeout=2):
            self.click_enabled_element(self.locator.CLEAR_FILTER_XPATH)

    def _load_the_filter(self):
        """
        Loads the filter object to selenium

        """
        self.wait_for_visibility(self.locator.OBJECT_SELECT_FILTER_XPATH)
        time.sleep(2)
        self.click_element_by_xpath(self.locator.OBJECT_SELECT_FILTER_XPATH)
        self.click_enabled_element(self.locator.PARAMETER_EDITOR_TAB)
        self.click_element_by_xpath(self.locator.PARAMETER_EDITOR_BODY_XPATH)
        self.click_element_by_xpath(self.locator.OBJECT_SELECT_FILTER_XPATH)

    def get_all_plans(self, timeout):
        """
        This Keyword returns all the available plans in system and count as the plane type wise

        :param timeout: int, timeout for the element be available to click

        :return: dict,plans types and count of the plans as per the plan type wise
        """
        plan_types = [u'Active configuration:', u'Delta configurations:', u'Inactive configurations:',
                      u'Planned configurations:']
        actual_plans = []
        self.click_enabled_element(self.locator.PLAN_SELECTION_DROP_DOWN, timeout)
        self.wait_for_visibility(self.locator.LIST_OF_PLANS_XPATH, timeout)
        for element in self._driver.find_elements_by_xpath(self.locator.LIST_OF_PLANS_XPATH):
            actual_plans.append(element.text)
        self.click_enabled_element(self.locator.PLAN_SELECTION_DROP_DOWN, timeout)
        return self._parse_available_plans(plan_types, actual_plans)

    @staticmethod
    def _parse_available_plans(plan_types, actual_plans):
        """
         This Keyword parse and returns all the available plans in system and count as the plane type wise

        :param plan_types: list, plans type that are present
        :param actual_plans: lis of available plans

        :return: dict,plans types and count of the plans as per the plan type wise
        """
        actual_index = [actual_plans.index(i) for i in plan_types if (i in actual_plans)]
        final_dict = {}
        for plan in plan_types:
            if plan not in actual_plans:
                final_dict[plan] = {'plan': None, 'count': 0}
        final_dict[actual_plans[actual_index[-1]]] = {'plans': actual_plans[actual_index[-1] + 1:],
                                                      'count': len(actual_plans[actual_index[-1] + 1:])}
        for curr, nxt in zip(actual_index, actual_index[1:] + ["end"]):
            if nxt == "end":
                final_dict[actual_plans[curr]] = {'plan': actual_plans[curr + 1:],
                                                  'count': len(actual_plans[curr + 1:])}
            else:
                final_dict[actual_plans[curr]] = {'plan': actual_plans[curr + 1:nxt],
                                                  'count': len(actual_plans[curr + 1:nxt])}
        return final_dict

    def expand_model_object_tree(self, object_name, timeout):
        """
         This Keyword will expand the MO Tree till the MO Structure given in the object name

        :param object_name: Model object in which parameter till the MO tree should expand
        :param timeout: int, timeout for the element be available to click        """
        self.wait_for_visibility(self.locator.SELECT_PLAN_XPATH.format(object_name.split('/')[0]))
        for mo in object_name.split('/'):
            if self.element_exists(self.locator.EXPAND_COLLAPSE_MO_XPATH.format(mo, 'expanded', timeout=1)):
                continue
            self.click_enabled_element(self.locator.EXPAND_COLLAPSE_MO_XPATH.format(mo, 'collapsed', timeout))

    def collapse_model_object(self, object_name, timeout):
        """
        This Keyword will collapse the MO Tree from  the MO Structure given in the object name

        :param object_name: Model object in which parameter from the MO tree should collapse
        :param timeout: int, timeout for the element be available to click
        """
        self.wait_for_visibility(self.locator.SELECT_PLAN_XPATH.format(object_name.split('/')[0]))
        for mo in object_name.split('/')[::-1]:
            if self.element_exists(self.locator.EXPAND_COLLAPSE_MO_XPATH.format(mo, 'collapsed', timeout=1)):
                continue
            self.click_enabled_element(self.locator.EXPAND_COLLAPSE_MO_XPATH.format(mo, 'expanded', timeout))

    def choose_plan(self, plan_name, inactive_configurations=False, timeout=60):
        """
        choose the plan to edited

        :param plan_name: str, plan that need to be selected
        :param inactive_configurations:  boolean, if True, checks whether the plan is ready to be activated
        selected, default False
        :param timeout: int, timeout for the element be available to click
        """
        self._clear_mo_filter()
        self.wait_for_visibility(self.locator.PLAN_SELECTION_DROP_DOWN, timeout)
        self.click_enabled_element(self.locator.PLAN_SELECTION_DROP_DOWN, timeout)
        if self.element_exists(self.locator.FILTER_TEXT_XPATH):
            filter_input = self.driver.find_element(By.XPATH, self.locator.FILTER_TEXT_XPATH)
            if filter_input.get_attribute("value"):
                filter_input.clear()
                filter_input.send_keys(Keys.SPACE)
        self.click_enabled_element(self.locator.CHOOSE_SELECT_PLAN_XPATH.format(plan_name, timeout))
        if inactive_configurations:
            choose_plan_status = self.wait_for_enable("//div[@class='notification-container']").text
            logging.debug("Print choose plan status info={}".format(choose_plan_status))

