    def load_commissioning_file_and_check_load_status(self, file_path, plan_name, validate_plan, timeout):
        """
        Load commissioning file and check load status

        :param file_path: str, scf file path
        :param plan_name: str, optional parameter, to edit the default plan name while loading scf
        :param validate_plan: str, optional parameter, default value is True which is means it will validate the plan.
                              If user doesn't want to validate plan during load scf pass validate plan as "False"
        :param timeout: int, timeout for the element be available to click for the element be available to click

        :return: Load scf success or failure with return of feedback message.
        """
        self.wait_for_enable(self.locator.CLICK_LOAD_SCF, timeout)
        self.click_enabled_element(self.locator.CLICK_LOAD_SCF)
        self.load_file_from_hidden_button(self.locator.LOAD_COMMISSIONING_FILE_BUTTON_SCRIPT,
                                          self.locator.LOAD_COMMISSIONING_FILE_BUTTON_XPATH, file_path, timeout)
        if plan_name:
            self.insert_text_to_enabled_element(self.locator.CHOOSE_LOAD_SCF_PLAN_EDIT_ID, plan_name)
        if not validate_plan:
            self.click_enabled_element(self.locator.VALIDATE_PLAN_OPTION_XPATH, timeout)
        self.wait_for_enable(self.locator.CLICK_LOAD_SCF_2, timeout)
        self.click_enabled_element(self.locator.CLICK_LOAD_SCF_2)
        load_scf_file_modal = LoadScfFileModal(driver=self._driver, version=self._version)
        load_scf_file_modal.wait_until_load_file_modal_appear(timeout)
        load_scf_file_modal.check_status_after_loading_scf_file(validate_plan, timeout)
        load_scf_file_modal.execute(validate_plan, timeout)
        load_status_output = self.get_text(self.locator.FEEDBACK_TEXT).splitlines()
        load_scf_file_modal.confirm()
        return load_status_output

