class CompareObjectsPageViewPanel(ViewPanel):

    def __init__(self, driver, version):
        super(CompareObjectsPageViewPanel, self).__init__(driver, version)
        self.common_actions = {
            'choose_plan': ConfigurationCommonAction(driver, version).choose_plan,
            'filter_and_select_the_object': ConfigurationCommonAction(driver, version).filter_and_select_the_object,
        }
        self.__dict__.update(self.common_actions)

    def compare_and_overwrite_all_parameters_right_to_left(self, base_object, object_to_be_compared, timeout):
        """
        This keyword compare all parameter values of the given two objects and overwrite base_object parameters vales
        with object_to_be_compared parameter values

        :param base_object: str, The Base object that has been select for comparison
        :param object_to_be_compared: str, Object selected in run time that has been compared with base_object
        :param timeout:int, timeout for the element be available to click
        """
        self._filter_and_choose_the_object_to_be_compared(base_object, timeout)
        self._select_and_compare_the_objects(object_to_be_compared)
        self.click_enabled_element(self.locator.COPY_ALL_FROM_RIGHT_TO_LEFT_XPATH)
        self.wait_for_visibility(self.locator.COPY_DIALOG_XPATH, timeout)
        self.wait_for_visibility(self.locator.COPY_MESSAGE_XPATH.format(object_to_be_compared, base_object),
                                 timeout)
        self.click_enabled_element(self.locator.OK_BUTTON_XPATH)
        self.wait_for_visibility(self.locator.UPDATE_STATUS_XPATH, timeout)
        self.wait_for_visibility(self.locator.COMPARE_SWITCH_ID, timeout)

    def compare_and_overwrite_all_parameters_left_to_right(self, base_object, object_to_be_compared, timeout):
        """
        This keyword compare all parameter values of the given two objects and overwrite
        object_to_be_compared parameters values with base_object parameter values

        :param base_object: str, The Base object that has been select for comparison
        :param object_to_be_compared: str, Object selected in run time that has been compared with base_object
        :param timeout:int, timeout for the element be available to click
        """
        self._filter_and_choose_the_object_to_be_compared(base_object, timeout)
        self._select_and_compare_the_objects(object_to_be_compared)
        self.click_enabled_element(self.locator.COPY_ALL_FROM_LEFT_TO_RIGHT_XPATH)
        self.wait_for_visibility(self.locator.COPY_DIALOG_XPATH, timeout)
        self.wait_for_visibility(self.locator.COPY_MESSAGE_XPATH.format(base_object, object_to_be_compared),
                                 timeout)
        self.click_enabled_element(self.locator.OK_BUTTON_XPATH)
        self.wait_for_visibility(self.locator.UPDATE_STATUS_XPATH, timeout)
        self.wait_for_visibility(self.locator.COMPARE_SWITCH_ID, timeout)

    def compare_and_overwrite_selected_parameter_left_to_right(self, base_object, object_to_be_compared, parameter,
                                                               timeout):
        """
        This keyword compare given parameter value of base object compare with selected object(object_to_be_compared)a
        nd overwrite parameter from base object to selected object

        :param base_object: str, The Base object that has been select for comparison
        :param object_to_be_compared: str, Object selected in run time that has been compared with base_object parameter
        :param parameter: str, Parameter that has been compared and overwrite
        :param timeout:int, timeout for the element be available to click
        """
        self._filter_and_choose_the_object_to_be_compared(base_object, timeout)
        self._select_and_compare_the_objects(object_to_be_compared)
        self.click_enabled_element(self.locator.COPY_PARAMETER_FROM_LEFT_TO_RIGHT.format(parameter), timeout)
        self.wait_for_invisibility(self.locator.PARAMETER_COPY_FINISHED_XPATH, timeout)

    def compare_and_overwrite_selected_parameter_right_to_left(self, base_object, object_to_be_compared, parameter,
                                                               timeout):
        """
        This keyword compare given parameter value of base object compare with selected object(object_to_be_compared)a
        nd overwrite parameter from selected object to base object

        :param base_object: str, The Base object that has been select for comparison
        :param object_to_be_compared: str, Object selected in run time that has been compared with base_object parameter
        :param parameter: str, Parameter that has been compared and overwrite
        :param timeout:int, timeout for the element be available to click
        """
        self._filter_and_choose_the_object_to_be_compared(base_object, timeout)
        self._select_and_compare_the_objects(object_to_be_compared)
        self.click_enabled_element(self.locator.COPY_PARAMETER_FROM_RIGHT_TO_LEFT.format(parameter), timeout)
        self.wait_for_invisibility(self.locator.PARAMETER_COPY_FINISHED_XPATH, timeout)

    def _filter_and_choose_the_object_to_be_compared(self, object_name, timeout):
        """
        filter the Model object for the selected plan and select it

        :param object_name: str, where object will be added in
        :param timeout: int, timeout for the element be available to click
        """
        last_level_object_name = object_name.split('/')[-1]

        self.wait_for_enable(self.locator.BASE_OBJECT_SELECT_FILTER_XPATH, timeout)

        if self.element_exists(self.locator.CLEAR_FILTER_XPATH, timeout=2):
            self.click_enabled_element(self.locator.CLEAR_FILTER_XPATH)
        if self.element_exists(self.locator.COMPARE_OBJECT_CONTAINER_XPATH, timeout=2):
            self.click_enabled_element(self.locator.COMPARE_OBJECT_CONTAINER_XPATH)
        self.insert_text_to_enable_element_and_enter(self.locator.OBJECT_SELECT_FILTER_XPATH,
                                                     last_level_object_name, timeout)
        self._select_valid_object(object_name, last_level_object_name, timeout)

    def _select_valid_object(self, object_name, last_level_object_name, timeout):
        """
        select the valid object out of all the matching object via filter and select the proper one

        :param object_name: str , name of the model object
        :param last_level_object_name: str, level of the object
        :param timeout: int, timeout for the element be available to click
        """
        self.wait_for_visibility(self.locator.OBJECT_NAME_XPATH.format(last_level_object_name), timeout)
        for element in self._driver.find_elements_by_xpath(
                self.locator.OBJECT_NAME_XPATH.format(last_level_object_name)):
            element.click()
            if self.element_exists(self.locator.CHECK_BASE_OBJECT_NAME_XPATH.format(object_name), timeout=20):
                return

    def _select_and_compare_the_objects(self, object_to_be_compared):
        """
        This key select the object to be compare with base object and perform show difference button

        :param object_to_be_compared: str, Object selected in run time that has been compared with base_object parameter

        """
        self.click_enabled_element(self.locator.COMPARE_OBJECT_DROP_DOWN_XPATH)
        time.sleep(3)
        self.click_enabled_element(self.locator.SELECT_OBJECT_BE_COMPARED_XPATH.format(object_to_be_compared))
        if not self.element_exists(self.locator.COMPARE_SWITCH_STATUS_XPATH, timeout=2):
            self.click_enabled_element(self.locator.COMPARE_SWITCH_ID)
